Game.prototype.shiftTerrain=function(delta,entities=true){delta=Math.max(0,Math.floor(delta));if(!delta)return;const rows=Math.min(delta,C.H);this.mask.copyWithin(rows*C.W,0,(C.H-rows)*C.W);this.mask.fill(0,0,rows*C.W);for(let i=0;i<this.heights.length;i++)this.heights[i]+=delta;for(const s of this.structures||[])s.y+=delta;for(const h of this.holes)h.y+=delta;if(entities){for(const u of this.units)if(u.hp>0&&(u.grounded||this.rope?.id===u.id))u.y+=delta;for(const grave of this.graves||[])grave.y+=delta;if(this.rope){this.rope.y+=delta;for(const p of this.rope.pivots||[])p.y+=delta;}if(this.ropeAim)this.ropeAim.y+=delta;const state=this.chapterState;if(state){for(const b of state.barrels)b.y+=delta;for(const b of state.crates){b.targetY+=delta;if(b.landed)b.y+=delta;}for(const m of state.marks)m.y+=delta;}}this.emit('terrainSink',{delta});};
const next=Game.prototype.nextTurn;Game.prototype.nextTurn=function(){next.call(this);if(this.phase==='ended')return;if(this.turn>=18&&this.turn<21&&this.sinking&&!this.sinking.warned){this.sinking.warned=true;this.emit('message',{text:'서든데스 예고! 양 팀 합산 21턴부터 지면이 가라앉습니다.'});}};
