Game.prototype.aimRopeAt=function(x,y){if(!this.canFire()||this.charging)return false;const hit=this.ropeRay(x,y);if(!hit){this.emit('message',{text:'사거리 720 안의 벽이나 발판을 터치해 주세요.'});return false;}this.ropeAim=hit;return true;};
Game.prototype.shootRope=function(){if(!this.canFire()||this.charging)return false;if(this.rope)return this.releaseRope();if(this.hook){this.hook=null;return true;}if(this.fuel<8){this.emit('message',{text:'로프 발사에는 이동력 8이 필요합니다.'});return false;}const u=this.active,a=this.angle*Math.PI/180,start={x:u.x,y:u.y-9},point=this.ropeAim||{x:start.x+Math.cos(a)*C.ROPE_RANGE,y:start.y-Math.sin(a)*C.ROPE_RANGE},dx=point.x-start.x,dy=point.y-start.y,d=Math.hypot(dx,dy);this.hook={...start,dx:dx/d,dy:dy/d,travel:0,id:u.id};this.ropeAim=null;this.emit('ropeShoot',{id:u.id,...start});return true;};
Game.prototype.attachRope=Game.prototype.shootRope;
Game.prototype.releaseRope=function(){const r=this.rope;if(!r)return false;const u=this.units[r.id];u.grounded=false;u.coyote=0;this.rope=null;this.ropeAdjust=0;this.emit('ropeRelease',{id:u.id});return true;};
Game.prototype.advanceHook=function(dt){const h=this.hook;if(!h)return;if(this.phase!=='aim'||this.weapon!==ROPE||this.activeId!==h.id||this.active.hp<=0){this.hook=null;return;}const u=this.units[h.id],distance=Math.min(1250*dt,C.ROPE_RANGE-h.travel);for(let i=0,n=Math.ceil(distance/.7);i<=n;i++){const d=Math.min(distance,i*.7),x=h.x+h.dx*d,y=h.y+h.dy*d;if(this.solid(x,y)){const length=Math.hypot(u.x-x,u.y-9-y);if(length>38){this.rope={x,y,length,targetLength:Math.max(52,length*.45),restLength:length,angle:Math.atan2(u.x-x,u.y-9-y),omega:0,radial:0,id:u.id,pivots:[],cartesian:true};u.grounded=false;u.coyote=0;delete u.landing;delete u.fallTop;this.fuel=Math.max(0,this.fuel-8);this.emit('ropeAttach',{id:u.id,x,y});}this.hook=null;return;}}h.x+=h.dx*distance;h.y+=h.dy*distance;h.travel+=distance;if(h.travel>=C.ROPE_RANGE||h.x<0||h.x>=C.W||h.y<0||h.y>=C.H){this.hook=null;this.emit('message',{text:'갈고리가 닿지 않았어요. 가까운 구조물을 터치해 보세요.'});}};
function lineClear(g,a,b,margin=10){const len=Math.hypot(b.x-a.x,b.y-a.y);for(let d=margin;d<len-margin;d+=2)if(g.solid(a.x+(b.x-a.x)*d/len,a.y+(b.y-a.y)*d/len))return false;return true;}
