const unit=Game.prototype.stepUnit;Game.prototype.stepUnit=function(u,dt){const r=this.rope;if(!r||r.id!==u.id)return unit.call(this,u,dt);r.pivots??=[];if(u.hp<=0||this.phase!=='aim'||this.fuel<=0||!this.solid(r.x,r.y)||r.pivots.some(p=>!this.solid(p.x,p.y))){this.releaseRope();return unit.call(this,u,dt);}const point={x:u.x,y:u.y-9};if(r.pivots.length){const previous=r.pivots[r.pivots.length-1];if(lineClear(this,point,previous,12)){const extra=Math.hypot(previous.x-r.x,previous.y-r.y);r.x=previous.x;r.y=previous.y;r.length+=extra;r.targetLength=(r.targetLength??r.length)+extra;r.pivots.pop();}}
if(!lineClear(this,point,r,14)&&r.pivots.length<4){const len=Math.hypot(r.x-point.x,r.y-point.y);for(let d=22;d<len-16;d+=1){const x=point.x+(r.x-point.x)*d/len,y=point.y+(r.y-point.y)*d/len;if(this.solid(x,y)){const extra=Math.hypot(r.x-x,r.y-y);r.pivots.push({x:r.x,y:r.y});r.x=x;r.y=y;r.length=Math.max(48,r.length-extra);r.targetLength=Math.max(48,(r.targetLength??r.length)-extra);break;}}}
const input=this.input||0,reel=this.ropeAdjust||0;this.fuel=Math.max(0,this.fuel-dt*(2+Math.abs(input)*3+Math.abs(reel)*5));r.targetLength=clamp((r.targetLength??r.restLength??r.length)+reel*200*dt,48,C.ROPE_RANGE);const previousLength=r.length;r.length+=clamp(r.targetLength-r.length,-180*dt,200*dt);r.restLength=r.targetLength;const gravity=this.options.layout===17?240:this.options.field?.type==='gravity'?430*this.options.field.value:430;u.vx=clamp((u.vx+input*330*dt)*Math.exp(-dt*.12),-650,650);u.vy=clamp(u.vy+gravity*dt,-650,650);let nx=u.x+u.vx*dt,ny=u.y+u.vy*dt,dx=nx-r.x,dy=ny-9-r.y,len=Math.hypot(dx,dy);if(len>r.length){nx=r.x+dx/len*r.length;ny=r.y+dy/len*r.length+9;}const oldX=u.x,oldY=u.y,n=Math.max(1,Math.ceil(Math.hypot(nx-oldX,ny-oldY)/1.5));for(let i=1;i<=n;i++){const x=oldX+(nx-oldX)*i/n,y=oldY+(ny-oldY)*i/n;if(free(this,x,y)){u.x=x;u.y=y;}else if(free(this,x,u.y))u.x=x;else if(free(this,u.x,y))u.y=y;}
u.vx=clamp((u.x-oldX)/dt,-650,650);u.vy=clamp((u.y-oldY)/dt,-650,650);dx=u.x-r.x;dy=u.y-9-r.y;len=Math.hypot(dx,dy);if(len>r.length+2){r.length=Math.min(C.ROPE_RANGE,len);if(Math.hypot(u.x-oldX,u.y-oldY)<.05)r.targetLength=Math.min(r.targetLength,r.length);}const outward=len?(u.vx*dx+u.vy*dy)/len:0;if(outward>0&&len>=r.length-.5){u.vx-=dx/len*outward;u.vy-=dy/len*outward;}r.angle=Math.atan2(dx,dy);r.omega=len?(u.vx*Math.cos(r.angle)-u.vy*Math.sin(r.angle))/len:0;r.radial=dt?(r.length-previousLength)/dt:0;r.cartesian=true;u.grounded=this.solid(u.x,u.y+19)&&u.vy>=0;u.groundTilt=0;u.face=input||u.face;u.walk+=Math.abs(input)*dt*4;if(u.y+8>this.water){this.releaseRope();this.damage(u,u.hp,undefined,'water');this.emit('splash',{x:u.x,y:this.water});}};
const step=Game.prototype.step;Game.prototype.step=function(dt=C.STEP){if(this.paused||this.phase==='ended')return;dt=clamp(dt,0,.05);if(this.sudden&&this.options.sinkingTerrain){this.sinking??={version:1,offset:0,carry:0,elapsed:0,warned:true};const s=this.sinking;s.elapsed+=dt;s.carry+=dt*Math.min(2.4,1.25+Math.max(0,this.turn-21)*.07);const delta=Math.floor(s.carry);if(delta){s.carry-=delta;s.offset+=delta;this.shiftTerrain(delta);}}this.advanceHook(dt);const flying=this.hook;this.hook=null;step.call(this,dt);if(flying&&this.phase==='aim'&&this.weapon===ROPE&&this.activeId===flying.id&&!this.rope)this.hook=flying;};
