const restore=Game.restore;Game.restore=function(data){const offset=Math.max(0,Math.min(2000,Math.floor(data?.sinking?.offset||0))),prepared={...data,holes:(data?.holes||[]).map(h=>({...h,y:h.y-offset})),rope:null},g=restore(prepared);if(!g)return g;g.options.sinkingTerrain=true;g.sinking=data.sinking?{...data.sinking}:{version:1,offset:0,carry:0,elapsed:0,warned:!!g.sudden};if(offset)g.shiftTerrain(offset,false);{const r=data.rope;if(r&&r.id===g.activeId&&[r.x,r.y,r.length].every(Number.isFinite)&&r.length>=38&&r.length<=C.ROPE_RANGE&&g.solid(r.x,r.y))g.rope=JSON.parse(JSON.stringify(r));}if(g.rope){g.rope.cartesian=true;g.rope.targetLength??=g.rope.restLength??g.rope.length;}if(data.hook&&data.hook.id===g.activeId&&[data.hook.x,data.hook.y,data.hook.dx,data.hook.dy,data.hook.travel].every(Number.isFinite)&&data.hook.travel>=0&&data.hook.travel<=C.ROPE_RANGE)g.hook={...data.hook};g.events=g.events.filter(e=>e.type!=='terrainSink');return g;};
